import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Header = ({ favourites = [] }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const location = useLocation();
  // In Header.js, at the top of the component:
  const Header = ({ favourites = [] }) => {  // Add default value
  // ... rest of your code
  };

  const navItems = [
    { path: '/', label: 'Home', icon: '🏠' },
    { path: '#properties', label: 'Properties', icon: '🔍' },
    { path: '#agents', label: 'Agents', icon: '👥' },
    { path: '#about', label: 'About', icon: 'ℹ️' },
    { path: '#contact', label: 'Contact', icon: '📞' },
  ];

  return (
    <>
      {/* Animated Background Elements */}
      <div className="animated-bg">
        <div className="particles">
          {Array.from({ length: 20 }).map((_, i) => (
            <div 
              key={i}
              className="particle"
              style={{
                width: `${Math.random() * 10 + 5}px`,
                height: `${Math.random() * 10 + 5}px`,
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                animationDelay: `${Math.random() * 5}s`,
                animationDuration: `${Math.random() * 20 + 10}s`,
              }}
            />
          ))}
        </div>
      </div>
      
      <div className="geometric-overlay"></div>
      <div className="gradient-mesh"></div>

      {/* Header */}
      <header className="header">
        <div className="container">
          <div className="header-content">
            {/* Enhanced Logo */}
            <div className="logo-container">
              <div className="logo-symbol">
                <div className="logo-house">
                  <div className="logo-roof"></div>
                  <div className="logo-base"></div>
                  <div className="logo-door"></div>
                </div>
                <div className="logo-glow"></div>
              </div>
              
              <div className="logo-text">
                <h1>Estate<span style={{ color: 'var(--secondary)' }}>Pro</span></h1>
                <div className="logo-subtitle">Find Your Dream</div>
              </div>
            </div>

            {/* Enhanced Navigation */}
            <nav className={`nav-enhanced ${isMenuOpen ? 'open' : ''}`}>
              {navItems.map((item) => (
                <a
                  key={item.label}
                  href={item.path}
                  className={`nav-item ${location.pathname === item.path ? 'active' : ''}`}
                >
                  <span className="nav-icon">{item.icon}</span>
                  {item.label}
                  <span className="nav-indicator"></span>
                </a>
              ))}
              
              {/* Favourites with Count */}
              <Link 
                to="/#favourites" 
                className="favourites-badge floating-element"
              >
                <span className="heart-icon">❤️</span>
                Favourites
                {favourites.length > 0 && (
                  <span className="favourites-count-bubble">
                    {favourites.length}
                  </span>
                )}
              </Link>
            </nav>

            {/* Mobile Menu Toggle */}
            <button 
              className={`menu-toggle ${isMenuOpen ? 'open' : ''}`}
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              aria-label="Toggle menu"
            >
              <span></span>
              <span></span>
              <span></span>
            </button>
          </div>
        </div>
      </header>
    </>
  );
};

export default Header;
